import{_ as e,o as t,c as s,ag as i}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-27（材料与能源 / MOF 催化 / 水处理）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-27-materials.md","filePath":"topics/materials/science-daily-2026-10-27-materials.md"}'),r={name:"topics/materials/science-daily-2026-10-27-materials.md"};function a(n,o,c,l,d,g){return t(),s("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-10-27-材料与能源-mof-催化-水处理" tabindex="-1">科学日报 · 2026-10-27（材料与能源 / MOF 催化 / 水处理） <a class="header-anchor" href="#科学日报-·-2026-10-27-材料与能源-mof-催化-水处理" aria-label="Permalink to &quot;科学日报 · 2026-10-27（材料与能源 / MOF 催化 / 水处理）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> — 第46期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-27-给铁基-mof-加一层「次级配位球」-痕量双氧水也能高效净水" tabindex="-1">科学日报 2026-10-27：给铁基 MOF 加一层「次级配位球」，痕量双氧水也能高效净水 <a class="header-anchor" href="#科学日报-2026-10-27-给铁基-mof-加一层「次级配位球」-痕量双氧水也能高效净水" aria-label="Permalink to &quot;科学日报 2026-10-27：给铁基 MOF 加一层「次级配位球」，痕量双氧水也能高效净水&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-27.md</code> ｜ DOI: 10.1038/s41467-026-79095-3 ｜ Nature Communications (2026)</p></blockquote><ul><li>问题：<strong>类芬顿（Fenton-like）反应</strong>要高效净水，两个障碍是 <strong>H₂O₂ 活化不足</strong>与 <strong>·OH 利用率低</strong>，根源在于 <strong>O–O 键能垒高</strong>、<strong>自由基寿命短</strong> —— 于是传统做法只能靠<strong>加大 H₂O₂ 剂量</strong>去补。</li><li>本工作：在铁基 MOF 中引入 <strong>吡啶 N 次级配位球（secondary coordination sphere）</strong>，即 <strong>N/MIL-53(Fe)</strong> —— 次级配位球与关键 <em><strong>OH 中间体强相互作用</strong>，<strong>降低 O–O 均裂能垒</strong>，并促成</em><em>原位生成寿命更长的吸附态 ·OH</em>*。</li><li>结果： <ul><li><strong>H₂O₂ 转化率约 90%</strong>，其中<strong>吸附态 ·OH 占总量的 90% 以上</strong>；</li><li>**痕量 H₂O₂（0.5 mM）**下 <strong>5 分钟内去除 98%</strong> 的双酚 A、四环素、苯酚、对氯苯酚与环丙沙星；</li><li><strong>H₂O₂ 消耗仅为已报道类芬顿催化剂的 3%–10%</strong>。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>ai-brain</code>）： <ol><li><strong>「改配位环境」战胜「加大剂量」</strong> —— 本条没有去改主活性中心（Fe），而是改<strong>它周围的第二层化学环境</strong>（吡啶 N），结果把反应<strong>从『先解离再反应』改成『就近生成并挂住』</strong>（吸附态而非自由 ·OH）。这与 10-23「FER 分子筛几何即功能：同框架两套可分别寻址位点」、10-25「SAM–钙钛矿解耦」同族：<strong>当反应卡在一个高能垒/短寿命环节时，先问是不是可以通过『第二层环境』（几何/配位/限域）改写路径，而不是靠增加驱动量。</strong></li><li><strong>可迁移判据：「用环境改变可控性，而不是用数量对抗能垒」</strong> —— 与 10-26「铁基 MOF」对应的 AI 侧同构是 <code>HarnessMM</code>（用<strong>守卫的持久决定</strong>替代每次重复推理，而不是靠更多算力）与本库自身的**「准入规则 &gt; 事后过滤」**。<strong>低消耗不是因为少做事，而是因为改动的是『路径』而不是『力度』。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ 第46期 科学板块</p></blockquote><p>关键词：科学日报第46期、类芬顿反应 Fenton-like、次级配位球 secondary coordination sphere、吡啶 N、N/MIL-53(Fe)、铁基 MOF、O-O 均裂能垒、吸附态 ·OH、H₂O₂ 转化率 90%、痕量 H₂O₂ 0.5 mM、5 分钟去 98%、H₂O₂ 消耗 3%-10%、双酚 A、四环素、环丙沙星、改配位环境胜过加大剂量、第二层环境改写路径、低消耗改路径不改力度、几何即功能</p><p>关联：<code>topics/materials/science-daily-2026-10-25-materials.md</code>（柔性钙钛矿 SAM 解耦）、<code>topics/materials/science-daily-2026-10-23-materials.md</code>（PtMn₃ 反铁磁 / FER 分子筛羰基化）、<code>topics/materials/index.md</code>、<code>topics/physics/index.md</code>、<code>topics/ai-brain/index.md</code></p>',10)])])}const O=e(r,[["render",a]]);export{p as __pageData,O as default};
